int ext4_ext_grow_in_inode(handle_t *handle, struct inode *inode, unsigned int flags)
{
    struct ext4_ext_path *path;
    struct ext4_extent_header *eh;
    struct ext4_extent_idx *ex_idx;
    ext4_lblk_t goal;
    int depth, err = 0;
    struct buffer_head *bh;
    unsigned int new_count;

    depth = ext4_ext_depth(inode);
    goal = ext4_ext_find_goal(inode, 0);

    err = ext4_alloc_blocks(handle, inode, goal, 1, &goal, flags);
    if (err)
        return err;

    bh = read_inode_block(inode, goal);
    if (!bh) {
        err = -ENOMEM;
        goto out;
    }

    eh = ext4_ext_header(bh);
    ext4_extent_init_header(inode, eh, 0);
    new_count = ext4_ext_count(eh) + 1;
    ext4_ext_index_set_count(eh, new_count);

    ex_idx = &eh->extents[0];
    for (unsigned int i = 0; i < ext4_ext_count(eh); ++i) {
        ex_idx->ei_block = 0;
        ex_idx->ei_leaf = 0;
    }

    memset((char *)ex_idx + new_count * sizeof(*ex_idx), 0,
           ext4_ext_max_entries(eh, depth) - new_count * sizeof(*ex_idx));

    mark_buffer_dirty(bh);
    inode->i_dirt = 1;

out:
    ext4_free_blocks(handle, inode, goal, 1, flags);
    return err;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    int error = 0;
    struct ext4_extent_idx *ex_idx;
    struct ext4_extent_header *eh;
    struct buffer_head *bh = NULL;
    ext4_lblk_t goal;

    goal = ext4_ext_find_goal(inode, 0);

    bh = ext4_alloc_block(handle, inode, goal, flags, &error);
    if (!bh)
        return error;

    ex_idx = (struct ext4_extent_idx *)bh->b_data;
    memset(ex_idx, 0, inode->i_sb->s_blocksize);

    eh = ext4_extent_header(inode);
    eh->eh_max = cpu_to_le16(eh->eh_max + 1);
    eh->eh_entries = cpu_to_le16(eh->eh_entries + 1);

    ext4_mark_inode_dirty(handle, inode);
    ext4_free_blocks(handle, inode, bh->b_blocknr, 1, flags);

    return error;
}

int ext4_ext_grow_inode(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct ext4_extent_header *eh;
    struct ext4_extent *ex;
    struct ext4_ext_path *path;
    ext4_lblk_t goal;
    int ret;
    struct buffer_head *bh;

    path = kzalloc(sizeof(struct ext4_ext_path) * (EXT4_MAXDEPTH), GFP_NOFS);
    if (!path)
        return -ENOMEM;

    eh = ext4_extent_header(inode);
    if (eh->eh_depth == 0)
        goal = 0;
    else
        goal = eh->eh_max;

    ret = ext4_alloc_block(handle, goal, flags, &goal, &bh);
    if (ret)
        goto out;

    ex = (struct ext4_extent *)bh->b_data;
    memset(ex, 0, inode->i_sb->s_blocksize);
    ext4_ext_read_idx(inode, bh, 0, ex);

    eh->eh_max++;
    eh->eh_depth++;
    eh->eh_entries++;

    ext4_mark_inode_dirty(handle, inode);

    brelse(bh);

out:
    kfree(path);
    return ret;
}

int ext4_ext_grow_path(handle_t *handle, struct inode *inode, unsigned int flags) {
    int err = 0;
    struct ext4_ext_path *path;
    ext4_lblk_t goal;
    struct buffer_head *bh;
    struct ext4_extent_header *eh;

    path = ext4_find_path(inode, 0);
    if (!path)
        return -ENOMEM;

    goal = ext4_ext_get_depth(inode) + 1;

    bh = ext4_alloc_block(handle, inode, goal, flags);
    if (IS_ERR(bh)) {
        err = PTR_ERR(bh);
        goto out;
    }

    eh = (struct ext4_extent_header *)bh->b_data;
    memset(eh, 0, sizeof(*eh));
    eh->eh_depth = ext4_ext_get_depth(inode) + 1;
    eh->eh_entries = 0;
    eh->eh_max = EXT4_EXTENT_INDEX_TAIL(eh);

    ext4_ext_update_header(inode, eh);

    mark_inode_dirty(handle, inode);

    brelse(bh);

out:
    ext4_free_path(path);
    return err;
}

int ext4_ext_grow_inodes(handle_t *handle, struct inode *inode, unsigned int flags)
{
    int err = 0;
    struct ext4_ext_path *path = NULL;
    struct ext4_extent_header *eh;
    struct ext4_extent_idx *new_idx;
    ext4_lblk_t new_block;

    /* Determine the goal block based on the current depth of the extent tree */
    if (ext4_ext_depth(inode) == 0) {
        new_block = ext4_ext_next_allocated_block(&path);
    } else {
        new_block = ext4_ext_pblk(&path[ext4_ext_depth(inode)]);
    }

    /* Allocate a new block for the extent index */
    new_block = ext4_new_block(handle, inode, new_block, flags, &err);
    if (err)
        goto out;

    /* Prepare the new block with existing data and zero unused space */
    err = ext4_ext_zero_blocks(handle, inode, new_block, 1, flags);
    if (err)
        goto out;

    new_idx = ext4_ext_kmem_get(handle, sizeof(struct ext4_extent_idx));
    if (!new_idx) {
        err = -ENOMEM;
        goto out;
    }

    /* Copy existing data into the new index block */
    ext4_ext_idx_init(new_idx, path[ext4_ext_depth(inode)].p_idx, new_block);

    /* Update the extent header with the new metadata */
    eh = ext4_ext_header(inode);
    eh->eh_entries++;
    eh->eh_max += 1;

    /* Mark the inode as dirty */
    err = ext4_mark_inode_dirty(handle, inode);
    if (err)
        goto out;

out:
    if (err)
        ext4_free_blocks(inode, new_block, 1, flags);

    return err;
}
